from collections import deque

def extend_range(ordered, start, end, increase):
    interval = end - start + 1
    indices = deque()
    for i in range(start, -1, -1):
        while len(indices) > 1 and interval - 2 * indices[0] < len(ordered[i]):
            indices.popleft()
        indices.append(i)
    best_index = 0
    doubled_count = 0
    score = 0
    all_score = {}
    for idx in indices:
        if intervals[start][0] - 2 * indices[0] < len(ordered[idx]) or intervals[idx][0] > 0:
            continue
        score = intervals[idx][1] + intervals[start][1]
        while start + 1 > best_index and score >= best_index:
            best_index += 1
        all_score[start] = best_index
        for i in range(idx, start):
            if ordered[i][0] + doubled_count < len(ordered[i]) or ordered[i][0] + doubled_count >= intervals[i][0]:
                all_score[i] = start
        start += 1
        while best_index >= start:
            # Counting pairs where the OR <= x, where one value each pair overlaps is easier with a single OR operation instead of the intersect from the previous scenario.
            doubled_count += best_index - idx
            if score >= best_index:
                break
            best_index -= 1
            if score <= best_index - idx or score >= best_index + (interval - 2 * indices[0]):
                break
            score -= best_index
    return all_score
