from collections import defaultdict, deque

def max_chocolates(n, chocolates, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        included = {}
        curr_count = 0
        q = deque([node])
        while q:
            current_node = q.popleft()
            for child in graph[current_node]:
                if child != parent:
                    included[child] = curr_count
                    curr_count += 1
                    dfs(child, current_node)
                    curr_count += 1
            included[current_node] = curr_count
        return included

    alice_included = {}
    bob_included = {-1: 0}
    alice_turn = 0

    def value_at(v, usps):
        if v not in usps:
            return 0
        l = usps[v]
        return ((alice_turn < len(alice_included) and alice_included[l] > bob_included[l]) or
                (alice_turn >= len(alice_included) or l > bob_included[-1]) and
                alice_included[l] if l in alice_included else -1)

    def take(included):
        total = 0
        v = None
        for i in sorted(included.keys()):
            l = included[i]
            if l < n and l in alice_included:
                if value_at(l, included) > value_at(n, included):
                    v = l
            elif l > 0 and l in alice_included and value_at(l-1, included) > value_at(n, included):
                v = l-1
            elif l > 0:
                v = max(v, l)
            if v:
                total += value_at(l, included)
                del included[l]
                if 0 not in included:  # sicher-
                    bob_included[l] += 1
                    if l > n - 1:  # über die top1...
                        if v == l:
                            del included[-1]
                        else:
                            del included[l - 1]
                break
        return total

    dp = {}
    for i in range(n):
        if i not in bob_included:
            dp[i] = 0

    max_value = 0
    for i in range(n):
        sub_dp = {k: dp[k] for k in dp}
        alice_included = dfs(i, i)
        values = []
        for node in range(n):
            if node in sub_dp:
                values.append(sub_dp[node])
        if not values:
            values.append(n)
        values.sort()
        pick = take(alice_included)
        if pick > max_value:
            max_value = pick
        # Reset Alice shared values so Bob can pick
        alice_included = {k for k in alice_included.keys()}
        for v in sub_dp:
            if not set.values(v) and v < n:
                dp[v] += sub_dp[0]
        for node in values:
            value = max(sub_dp[node], dp[node])
            if value and value > max_value:
                max_value = value
    return max_value

