def find_longest_increasing_subsequence(arr, niis):
    memo = {}
    def find LIS(i):
        if i == 0:
            return 0
        if i in memo:
            return memo[i]
        a, b = 0, 0
        if niis[i] != -1:
            for j in range(max(i, niis[i] - 1), i):
                a = max(a, find LIS(j))
            return b
        for j in range(max(i - 1, niis[i]), i):
            b = max(b, find LIS(j) + 1)
        a = max(0, a)
        b = max(1, b)
        memo[i] = a + b
        return b
    return find LIS(len(arr) - 1)

def solve(bases, niis, to_add):
    m, dem = (len(abs(x)), len(to_add)) for x in bases if x >= 0
    a, b = (x * (len(bases) - dem), x * (len(to_add) - dem)) for x in bases if x < 0
    niis.extend(m)
    bases.extend(niis)
    b.sort()
    a = set(a)
    b = set(b)
    bases = list(a & b)
    bases.sort()
    m = len(bases)
    if m * 2 - (len(b)-1) == m:
        return b
    elif m * 5 - (len(b)-1) == m:
        return b
    elif (m * m / 2) - m == m:
        return b[5:]
    else:
        return b[5:6]

