def is_good_subarray(A, K, n):
    prefix_xor = [0 for _ in range(n)]
    left = 0
    for right in range(n):
        # Apply the XOR operation
        prefix_xor[right] = prefix_xor[right - 1] ^ A[right]
        # Get the prefix XOR up to the current right index
        # If the prefix XOR is at least K, return [left, right]
        if prefix_xor[right] >= K:
            return [left, right]
        # Check if [right] is a candidate
        if prefix_xor[right] + A[right] < K and prefix_xor[right-1] <= K:
            left = right
    return -1

def find_min_good_subarray_cnt(arr, K):
    N = len(arr)
    results = []
    for i in range(1, N):
        xor_array = 0
        for j in range(0, i):
            xor_array ^= arr[j]
        # Check if there exists a subarray with XOR >= K
        if xor_array >= K or xor_array + arr[i] < K:
            results.append(i)
    return results

def find_min_good_subarray(arr, K):
    results = find_min_good_subarray_cnt(arr, K)
    if results:
        return min(result[1] - result[0] for result in results)
    else:
        return -1

