from typing import List

def find_lis_size(nums: List[int], used: List[bool]) -> int:
    n = len(nums)
    used = [False] * (n + 1)
    used[0] = True
    stack = [0]
    for i in range(1, n + 1):
        if used[i]:
            continue
        while stack and nums[stack[-1]] < nums[i]:
            used[stack.pop()] = False
        if nums[i] != nums[i - 1]:
            stack.append(i)
            used[i] = True
    return len(stack)

def main(nums: List[int], used: List[bool], m: int, numbers: List[int]) -> List[int]:
    remaining = set(range(1, len(nums) + 1))
    for num in numbers:
        remaining.discard(num)
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] in remaining and not used[nums[i]]:
            continue
        while remaining:
            next_num = sorted(remaining - set([nums[i], -1]))[0]
            if nums[i] != next_num:
                remaining.remove(next_num)
                nums[i] = next_num
                break
    return nums

if __name__ == "__main__":
    n = int(input())
    nums = list(map(int, input().split()))
    used = [False] * len(nums)
    m = int(input())
    numbers = list(map(int, input().split()))
    result = main(nums, used, m, numbers)
    print(" ".join(map(str, result)))
