from collections import defaultdict, deque

def max_chocolates(n, chocolates, adj_list):
    visited = [False] * n
    queue = deque()
    connections = defaultdict(set)

    for i, (u, v) in enumerate(adj_list):
        connections[u].add(v)
        connections[v].add(u)

    # Initialize the queue with the root vertices
    for connection in connections.keys():
        if not visited[connection]:
            queue.append(connection)

    result = 0

    while queue:
        total_q = 0
        for _ in range(len(queue)):
            current = queue.popleft()
            for neighbor in connections[current]:
                visited[neighbor] = True
                connections[current] -= {neighbor}
                connections[neighbor] -= {current}
                total_q += chocolates[neighbor]
                if not connections[neighbor]:
                    queue.append(neighbor)
                    connections.pop(neighbor)
                    break
        if total_q > result:
            result = total_q

    return result

# Example usage:
# adj_list = [list of lists from the problem description]
# max_chocolates(10, [1, 2, 3, 4, 5, 6, 7, 8, 9], adj_list)
