from collections import defaultdict

def find_gaps(positions):
    gap_positions = defaultdict(int)
    for position in positions[:-1]:
        if position == -1:
            gap_positions[positions.index(position)] += 1
    return gap_positions

def fill_gaps(positions, new_elements, used_count):
    gap_positions = find_gaps(positions)
    used_count += len(positions) - len(new_elements)
    for num in new_elements:
        if num not in gap_positions or gap_positions[num] == 0:
            used_count += 1
            rev_gap_positions = {v: k for k, v in gap_positions.items()}
            gap_positions[num] -= 1
            if num in rev_gap_positions:
                rev_gap_positions.pop(num)
    return used_count, gap_positions

def create_filled_sequence(positions, used_count, used_elements, gaps):
    filled_sequence = []
    gap_count = {}
    for gap in sorted(gaps.keys()):
        if used_count <= 0:
            break
        filled_sequence.append(positions[gap])
        gap_count[gap] = 1
        used_count -= 1
    for i in range(1, len(filled_sequence)):
        if gap_count[filled_sequence[i]] == 1 and filled_sequence[i-1] < filled_sequence[i]:
            gap_count[filled_sequence[i-1]] = 0
    return [filled_sequence[i] for i in range(len(filled_sequence)) if not gap_count[i]]

def solve(positions, used_elements, m):
    # Edge Case - Check if all positions are filled
    if used_elements:
        return create_filled_sequence(positions, used_elements[0], used_elements[0], defaultdict(int))
    else:
        used_elements = find_gaps(positions) if used_elements else {}
        for element in reversed(range(1, 1000)):
            if used_elements[element] and element < positions[-1]: 
                used_elements[element] -= 1
                used_elements[element], position = m - 1, element 
                if 0 < position < len(positions):
                    return create_filled_sequence(positions, used_elements, list(positions)[:-1])
                else:
                    used_elements[element] += 1
                    continue
        return create_filled_sequence([1,2]*((2**len(positions)-1)//positions[0] + 1))
