def shortest_good_subarray(N, K, A):
    prefix_sum = [0] * (N + 1)
    xor_sum = [0] * (N + 1)

    for i in range(1, N + 1):
        prefix_sum[i] = prefix_sum[i - 1] ^ A[i - 1]
        xor_sum[i] = xor_sum[i - 1] ^ K

    min_length = float('inf')
    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            xor = xor_sum[j] ^ xor_sum[i]
            if xor >= 0:
                length = j - i
                min_length = min(min_length, length)

    if min_length == float('inf'):
        return -1
    else:
        return min_length

