def min_inconvenience(n, L, a, b):
    max_distance_i = {i: j for i, j in zip(a, b)}
    max_distance_i = {max(i, j): i for i, j in max_distance_i.items()}

    magitudes = {i[0]: j for i, j in zip(a, b)}
    for i in a + b:
        magitudes[i] = min(max_distance_i[i], L-max_distance_i[i])

    minimal_inconvenience = L
    for i in range(n):
        for j in range(n):
            distance = abs(magitudes[i] - max_distance_i[j])
            minimal_inconvenience = min(minimal_inconvenience, distance)

    for i in range(1, 2*n):
        if i % 2:
            minimal_inconvenience = min(minimal_inconvenience, L - magitudes[i])

    return minimal_inconvenience

