        if i == t or a[i] == t or (nxt_counter < len(a) and a[i] == nxt[nxt_counter]):
            if a[i] != nxt[nxt_counter]:
                indices.append(i)
                nxt_counter += 1
    return indices

def ai(a):
    n = len(a)
