from heapq import heappush, heappop

def find_max_increasing_subsequence(arr):
    gap_positions = []
    result = []

    # Push positions of gaps into a heap
    for i, num in enumerate(arr):
        if num == -1:
            heappush(gap_positions, i)

    stack = []
    # Find the most recent gap
    for pos in reversed(gap_positions):
        stack.append([pos, 1])
        while stack and stack[-1][1] >= len(result) + 1:
            result.insert(stack.pop()[0], result[-1])

    # Construct the final result
    for i, num in enumerate(arr):
        if num == -1:
            result.append(-1)
            stack.append([-1, 1])
            while len(stack) > 1 and stack[-1][0] < stack[-2][0]:
                result.insert(stack.pop()[0], result[-1])
            while len(stack) > 1 and stack[-1][0] > stack[-2][0]:
                stack.pop()

    return ' '.join(map(str, result))

