def min_k(N):
    # Find the binary representation of N
    binary_N = bin(N)[2:]

    # Initialize the sum of bits on odd positions
    sum_odd_bits = 0

    # Iterate through each bit in reverse
    for i in range(len(binary_N)-1, -1, -2):
        # Add the bit to the sum only if it is set (1)
        if binary_N[i] == '1':
            sum_odd_bits += 1

    # Iterate through each bit in reverse
    for i in range(len(binary_N)-2, -1, -2):
        # If the sum of odd-position bits reached or exceeded N, return the current K
        if sum_odd_bits >= N:
            return int(binary_N, 2) + 1

    # If the loop completes without returning, the minimum K is one less than N
    return int(binary_N, 2) 

T = int(input())
